def solve():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        R = int(input[ptr])
        C = int(input[ptr+1])
        K = int(input[ptr+2])
        ptr += 3
        reachable = set()
        for k in range(K + 1):
            for dr in [-k, -k+1, ..., k]:
                for dc in [-k, -k+1, ..., k]:
                    if abs(dr) + abs(dc) <= k:
                        r = R + dr
                        c = C + dc
                        if 1 <= r <= 8 and 1 <= c <= 8:
                            reachable.add((r, c))
        print(len(reachable))

solve()
